{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Choose the scan volume to segment",
      "simple": "Select the CT volume you want to use for the skull segmentation.",
      "detailed": "This volume is the foundation of the entire plan: the bone model used for implant planning is derived from it. Pick the CT dataset with clear bone detail and minimal artifact so the later segmentation is reliable."
    },
    {
      "step_id": "cb_step_2",
      "title": "Create the skull segmentation",
      "simple": "Create a new segmentation to hold the skull model.",
      "detailed": "A dedicated segmentation stores the bony mask that will be used for cutting and implant planning. Keeping it separate from the original scan makes the next steps easier to review and edit."
    },
    {
      "step_id": "cb_step_3",
      "title": "Add a segment for the skull",
      "simple": "Add a segment and rename it to Cranial_Segment.",
      "detailed": "This gives you a named label inside the segmentation to contain the skull bone. Everything generated by thresholding will be stored here, so future steps can refer to this bone model."
    },
    {
      "step_id": "cb_step_4",
      "title": "Open the threshold tool",
      "simple": "Click the Threshold button.",
      "detailed": "Thresholding selects tissues based on density, which is the first step in separating bone from soft tissue and air. It lets you define the Hounsfield range that corresponds to the skull."
    },
    {
      "step_id": "cb_step_5",
      "title": "Set the threshold range for bone",
      "simple": "Adjust the range bar so the highlighted region covers the skull and excludes soft tissue.",
      "detailed": "The correct density range captures cortical and trabecular bone while avoiding the surrounding soft tissue and air. Aim for a range where the whole skull is highlighted without filling in the brain or skin."
    },
    {
      "step_id": "cb_step_6",
      "title": "Apply the threshold segmentation",
      "simple": "Click Apply to generate the initial skull mask.",
      "detailed": "This converts the selected density range into a bony segmentation mask. The result is the starting skull model for the subsequent symmetry and cutting steps."
    },
    {
      "step_id": "cb_step_7",
      "title": "Choose the skull segmentation",
      "simple": "Select the skull segmentation you created in the previous steps.",
      "detailed": "The planning extension needs this skull model to compute the symmetry plane and plan the cuts. Choosing the correct segmentation ensures all subsequent measurements are made on the intended bone."
    },
    {
      "step_id": "cb_step_8",
      "title": "Choose the entry-points list",
      "simple": "Select the point list containing your planned entry points.",
      "detailed": "Entry points define where the implants are intended to enter the bone. The extension uses these landmarks to orient the planning steps and generate implant trajectories that start at the desired locations."
    },
    {
      "step_id": "cb_step_9",
      "title": "Compute the symmetry plane",
      "simple": "Click the \"1. Compute symmetry plane\" button.",
      "detailed": "This calculates the midsagittal plane of the skull, the anatomical reference for left-right symmetry. It is the basis for orienting later cuts and ensuring the implant plan is balanced."
    },
    {
      "step_id": "cb_step_10",
      "title": "Decide whether to fine-tune the symmetry plane",
      "simple": "If the computed symmetry plane looks incorrect, choose Yes; otherwise choose No to skip.",
      "detailed": "For zygomatic implant planning, an accurate sagittal plane is important because it anchors the orientation of all subsequent cuts. Choose Yes only if the plane is visibly malpositioned or asymmetric."
    },
    {
      "step_id": "cb_step_11",
      "title": "Adjust the symmetry plane",
      "simple": "Move and rotate the plane in the 3D view so it follows the midline of the skull, then click Done.",
      "detailed": "This sets the anatomical reference for left-right symmetry. Align the plane through the midline of the skull, ideally passing from the nasion to the external occipital protuberance, so later mirrored measurements are reliable."
    },
    {
      "step_id": "cb_step_12",
      "title": "Apply the plane adjustment",
      "simple": "Click the \"Apply adjustment\" button.",
      "detailed": "This commits the corrected symmetry plane to the planning workflow. The next cutting and orientation steps will use this refined reference."
    },
    {
      "step_id": "cb_step_13",
      "title": "Set the crop radius",
      "simple": "Adjust the range bar to choose how much of the skull to keep around the entry points.",
      "detailed": "The crop radius determines the cylindrical region of skull centered on the planned treatment area. A radius that is too small may cut through the implant bed; one that is too large keeps unnecessary bone in the model."
    },
    {
      "step_id": "cb_step_14",
      "title": "Cut the skull into a cylinder",
      "simple": "Click the \"2. Cut skull (cylinder)\" button.",
      "detailed": "This removes the parts of the skull outside the chosen radius, leaving a cylindrical bone volume around the treatment site. The reduced model makes the maxilla and zygomatic processes easier to isolate for implant planning."
    },
    {
      "step_id": "cb_step_15",
      "title": "Decide if the mandible is still attached",
      "simple": "If the lower jaw is still attached to the upper jaw, choose Yes; otherwise choose No to skip.",
      "detailed": "The lower jaw must be separated from the maxilla to plan zygomatic implant trajectories cleanly. Choose Yes if the skull remains as one connected bone after the cylindrical cut."
    },
    {
      "step_id": "cb_step_16",
      "title": "Separate maxilla and mandible",
      "simple": "Click the \"3. Separate maxilla / mandible\" button.",
      "detailed": "This creates a clean separation between the upper and lower jaws so the planned implants remain confined to the maxillary and zygomatic bone. It prevents the mandible from interfering with the generated paths."
    },
    {
      "step_id": "cb_step_17",
      "title": "Decide whether to fine-tune the separation plane",
      "simple": "If the separation between the jaws looks incorrect, choose Yes; otherwise choose No to skip.",
      "detailed": "A poor separation can leave parts of the mandible attached or cut too far into the maxilla. Manual correction is useful when the automatic separation plane does not follow the intended anatomical boundary."
    },
    {
      "step_id": "cb_step_18",
      "title": "Adjust the separation plane",
      "simple": "Move and rotate the plane so it sits in the gap between the upper and lower jaws, then click Done.",
      "detailed": "This defines the cut boundary that separates the maxilla from the mandible. Position the plane along the natural joint space so the lower jaw is completely removed from the planning model."
    },
    {
      "step_id": "cb_step_19",
      "title": "Apply the separation",
      "simple": "Click the \"Apply separation\" button.",
      "detailed": "This applies the corrected separation plane and finalizes the maxilla-mandible split. The remaining upper skull model is now ready for zygomatic bone identification."
    },
    {
      "step_id": "cb_step_20",
      "title": "Identify the zygomatic bones",
      "simple": "Click the \"4. Identify zygomatic bones\" button.",
      "detailed": "This isolates the cheekbone region that will host the implants. Accurate identification of the zygomatic bones defines the surgical target for the planned implant trajectories."
    },
    {
      "step_id": "cb_step_21",
      "title": "Decide whether to fine-tune the boundary planes",
      "simple": "If the identified zygomatic bone region needs adjustment, choose Yes; otherwise choose No to skip.",
      "detailed": "Boundary planes define the edges of the bone segment used for implant planning. If the automatic identification includes too much or too little bone, manual adjustment gives you a more accurate surgical target."
    },
    {
      "step_id": "cb_step_22",
      "title": "Adjust the boundary planes",
      "simple": "Move and rotate the plane or planes so they outline the desired zygomatic bone boundary, then click Done.",
      "detailed": "This trims the implant planning region to the intended part of the zygomatic bone. Align the boundaries to include the thick bone available for the implant while excluding adjacent structures you do not want to cross."
    },
    {
      "step_id": "cb_step_23",
      "title": "Apply the boundary adjustments",
      "simple": "Click the \"Apply boundaries\" button.",
      "detailed": "This commits the corrected boundaries and updates the zygomatic bone model. The refined region is now used to generate safe implant paths."
    },
    {
      "step_id": "cb_step_24",
      "title": "Generate implant paths",
      "simple": "Click the \"5. Generate Implant paths\" button.",
      "detailed": "This creates planned implant trajectories from the entry points through the zygomatic bone. The paths take into account the available bone volume and are the main output used for surgical guidance."
    },
    {
      "step_id": "cb_step_25",
      "title": "Decide whether to adjust the implant paths",
      "simple": "If the generated paths are safe and well positioned, choose No to finish; otherwise choose Yes to refine them.",
      "detailed": "Automatic paths may need manual correction if they pass too close to the orbit, sinus, or the edge of the bone. Choose Yes if you want to reposition any trajectory before finalizing the plan."
    },
    {
      "step_id": "cb_step_26",
      "title": "Adjust the implant paths",
      "simple": "Reposition one path line in the 3D view so it runs cleanly through the bone, then click Done.",
      "detailed": "Each path line represents one implant trajectory. Adjust the line so the implant stays within the available zygomatic bone and avoids critical structures such as the orbit and sinuses."
    },
    {
      "step_id": "cb_step_27",
      "title": "Apply the adjusted paths",
      "simple": "Click the \"Apply paths\" button.",
      "detailed": "This finalizes the manual path corrections and locks in the planned implant trajectories. The result is the complete surgical plan for the zygomatic implant placement."
    }
  ]
}
